        price_guard_pct DECIMAL(5,2) NOT NULL DEFAULT 0, description TEXT NULL, specs MEDIUMTEXT NULL, warranty VARCHAR(120) NULL, weight_g INT NULL, dims VARCHAR(60) NULL,
        image VARCHAR(255) NULL, active TINYINT NOT NULL DEFAULT 1, link_token CHAR(16) NULL, min_stock INT NOT NULL DEFAULT 0, created_at DATETIME NOT NULL, updated_at DATETIME NULL, KEY(barcode))$E",
    "CREATE TABLE IF NOT EXISTS product_variants (id INT AUTO_INCREMENT PRIMARY KEY, product_id INT NOT NULL, vcode CHAR(2) NOT NULL, title VARCHAR(120) NOT NULL, code CHAR(20) NOT NULL UNIQUE,
        barcode VARCHAR(60) NULL, price_delta BIGINT NOT NULL DEFAULT 0, active TINYINT NOT NULL DEFAULT 1, UNIQUE KEY(product_id, vcode), KEY(barcode))$E",
    "CREATE TABLE IF NOT EXISTS price_history (id INT AUTO_INCREMENT PRIMARY KEY, product_id INT NOT NULL, old_price BIGINT NOT NULL, new_price BIGINT NOT NULL, at DATETIME NOT NULL, user_id INT NULL, KEY(product_id))$E",
    "CREATE TABLE IF NOT EXISTS grades (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(60) NOT NULL, kind VARCHAR(10) NOT NULL DEFAULT 'customer', disc_pct DECIMAL(5,2) NOT NULL DEFAULT 0)$E",
    "CREATE TABLE IF NOT EXISTS product_grade_prices (product_id INT NOT NULL, grade_id INT NOT NULL, disc_single DECIMAL(5,2) NOT NULL DEFAULT 0, disc_max DECIMAL(5,2) NOT NULL DEFAULT 0,
