    // ── خرید
    "CREATE TABLE IF NOT EXISTS suppliers (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(160) NOT NULL, national_id VARCHAR(20) NULL, mobile VARCHAR(15) NULL, phone VARCHAR(40) NULL,
