    "CREATE TABLE IF NOT EXISTS supplier_payments (id INT AUTO_INCREMENT PRIMARY KEY, supplier_id INT NOT NULL, pi_id INT NULL, amount BIGINT NOT NULL, method VARCHAR(12) NOT NULL, bank_account_id INT NULL,
        cheque_id INT NULL, d DATE NOT NULL, note VARCHAR(300) NULL, created_by INT NULL, created_at DATETIME NOT NULL, KEY(supplier_id))$E",
    // ── انبار
    "CREATE TABLE IF NOT EXISTS lots (id INT AUTO_INCREMENT PRIMARY KEY, product_id INT NOT NULL, variant_id INT NULL, warehouse_id INT NOT NULL, seller_code CHAR(2) NOT NULL DEFAULT '00',
