    // ── فروش
    "CREATE TABLE IF NOT EXISTS shifts (id INT AUTO_INCREMENT PRIMARY KEY, cashbox_id INT NOT NULL, user_id INT NOT NULL, status VARCHAR(8) NOT NULL DEFAULT 'open', opening_cash BIGINT NOT NULL DEFAULT 0,
