    "CREATE TABLE IF NOT EXISTS receipts (id INT AUTO_INCREMENT PRIMARY KEY, sale_id INT NULL, return_id INT NULL, shift_id INT NULL, cashbox_id INT NULL, method VARCHAR(12) NOT NULL, amount BIGINT NOT NULL,
