    "CREATE TABLE IF NOT EXISTS channels (id INT AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, kind VARCHAR(12) NOT NULL DEFAULT 'online', user_id INT NULL,
