    "CREATE TABLE IF NOT EXISTS channel_products (channel_id INT NOT NULL, product_id INT NOT NULL, price_override BIGINT NULL, PRIMARY KEY(channel_id, product_id))$E",
    "CREATE TABLE IF NOT EXISTS channel_orders (id INT AUTO_INCREMENT PRIMARY KEY, channel_id INT NOT NULL, ext_id VARCHAR(80) NOT NULL, sale_id INT NULL, payload MEDIUMTEXT NULL, status VARCHAR(12) NOT NULL DEFAULT 'ok',
        created_at DATETIME NOT NULL, UNIQUE KEY(channel_id, ext_id))$E",
    "CREATE TABLE IF NOT EXISTS channel_ledger (id INT AUTO_INCREMENT PRIMARY KEY, channel_id INT NOT NULL, amount BIGINT NOT NULL, kind VARCHAR(12) NOT NULL, ref_type VARCHAR(20) NULL, ref_id INT NULL,
