    "CREATE TABLE IF NOT EXISTS catalog_changes (id BIGINT AUTO_INCREMENT PRIMARY KEY, product_id INT NOT NULL, at DATETIME NOT NULL, KEY(at))$E",
    // ── کارکنان
    "CREATE TABLE IF NOT EXISTS staff_ledger (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, amount BIGINT NOT NULL, kind VARCHAR(12) NOT NULL, ref_type VARCHAR(20) NULL, ref_id INT NULL,
