    "CREATE TABLE IF NOT EXISTS commission_rules (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, base VARCHAR(10) NOT NULL DEFAULT 'profit', user_id INT NULL, category_id INT NULL, channel_id INT NULL,
