    "CREATE TABLE IF NOT EXISTS staff_targets (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, ym CHAR(7) NOT NULL, target BIGINT NOT NULL, UNIQUE KEY(user_id, ym))$E",
    "CREATE TABLE IF NOT EXISTS employees (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, national_id VARCHAR(10) NULL, mobile VARCHAR(15) NULL, unit VARCHAR(80) NULL, position VARCHAR(80) NULL,
