    "CREATE TABLE IF NOT EXISTS contracts (id INT AUTO_INCREMENT PRIMARY KEY, employee_id INT NOT NULL, title VARCHAR(160) NOT NULL, body MEDIUMTEXT NOT NULL, start_date DATE NOT NULL, end_date DATE NULL,
