    "CREATE TABLE IF NOT EXISTS payslips (id INT AUTO_INCREMENT PRIMARY KEY, employee_id INT NOT NULL, ym CHAR(7) NOT NULL, items MEDIUMTEXT NOT NULL, gross BIGINT NOT NULL, deductions BIGINT NOT NULL, net BIGINT NOT NULL,
        status VARCHAR(10) NOT NULL DEFAULT 'calc', paid_at DATETIME NULL, created_at DATETIME NOT NULL, UNIQUE KEY(employee_id, ym))$E",
    // ── مشتریان
    "CREATE TABLE IF NOT EXISTS customers (id INT AUTO_INCREMENT PRIMARY KEY, kind VARCHAR(6) NOT NULL DEFAULT 'person', name VARCHAR(160) NOT NULL, mobile VARCHAR(15) NULL UNIQUE, national_id VARCHAR(20) NULL,
