    "CREATE TABLE IF NOT EXISTS customer_people (id INT AUTO_INCREMENT PRIMARY KEY, customer_id INT NOT NULL, name VARCHAR(120) NOT NULL, role VARCHAR(80) NULL, mobile VARCHAR(15) NULL, KEY(customer_id), KEY(mobile))$E",
    "CREATE TABLE IF NOT EXISTS customer_ledger (id INT AUTO_INCREMENT PRIMARY KEY, customer_id INT NOT NULL, amount BIGINT NOT NULL, kind VARCHAR(12) NOT NULL, ref_type VARCHAR(20) NULL, ref_id INT NULL,
