    "CREATE TABLE IF NOT EXISTS calls (id INT AUTO_INCREMENT PRIMARY KEY, customer_id INT NOT NULL, user_id INT NULL, at DATETIME NOT NULL, direction VARCHAR(4) NOT NULL DEFAULT 'out', result VARCHAR(20) NOT NULL,
        note TEXT NULL, internal TINYINT NOT NULL DEFAULT 0, next_at DATE NULL, done TINYINT NOT NULL DEFAULT 0, KEY(customer_id), KEY(next_at))$E",
    // ── مالی
    "CREATE TABLE IF NOT EXISTS accounts (id INT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(12) NOT NULL UNIQUE, name VARCHAR(160) NOT NULL, parent_id INT NULL, level VARCHAR(8) NOT NULL DEFAULT 'moein',
