    "CREATE TABLE IF NOT EXISTS journals (id INT AUTO_INCREMENT PRIMARY KEY, number INT NULL, d DATE NOT NULL, descr VARCHAR(400) NOT NULL, source_type VARCHAR(20) NOT NULL, source_id VARCHAR(40) NOT NULL,
