    "CREATE TABLE IF NOT EXISTS bank_accounts (id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(120) NOT NULL, bank VARCHAR(80) NULL, iban VARCHAR(30) NULL, card_no VARCHAR(20) NULL, account_no VARCHAR(40) NULL,
        owner VARCHAR(120) NULL, active TINYINT NOT NULL DEFAULT 1)$E",
    "CREATE TABLE IF NOT EXISTS cheques (id INT AUTO_INCREMENT PRIMARY KEY, direction VARCHAR(4) NOT NULL, number VARCHAR(40) NOT NULL, bank VARCHAR(80) NULL, amount BIGINT NOT NULL, due_date DATE NOT NULL,
        party_type VARCHAR(12) NULL, party_id INT NULL, party_name VARCHAR(160) NULL, status VARCHAR(12) NOT NULL DEFAULT 'pending', bank_account_id INT NULL, note VARCHAR(300) NULL, created_at DATETIME NOT NULL, KEY(due_date))$E",
    "CREATE TABLE IF NOT EXISTS bank_reconcile (id INT AUTO_INCREMENT PRIMARY KEY, bank_account_id INT NOT NULL, d DATE NOT NULL, statement_balance BIGINT NOT NULL, book_balance BIGINT NOT NULL, diff BIGINT NOT NULL,
        note VARCHAR(300) NULL, user_id INT NULL, created_at DATETIME NOT NULL)$E",
    "CREATE TABLE IF NOT EXISTS acc_partners (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, coef DECIMAL(8,3) NOT NULL DEFAULT 1, active TINYINT NOT NULL DEFAULT 1)$E",
    "CREATE TABLE IF NOT EXISTS acc_expenses (id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(160) NOT NULL, amount BIGINT NOT NULL, monthly TINYINT NOT NULL DEFAULT 0, ym CHAR(7) NULL, from_ym CHAR(7) NULL, to_ym CHAR(7) NULL, created_at DATETIME NOT NULL)$E",
    "CREATE TABLE IF NOT EXISTS acc_settles (id INT AUTO_INCREMENT PRIMARY KEY, partner_id INT NOT NULL, amount BIGINT NOT NULL, d DATE NOT NULL, note VARCHAR(300) NULL, created_at DATETIME NOT NULL)$E",
    ];
    return [$m1];
}
